const sd = $getWorkflowStaticData('global');
sd.stockRows = [];
sd.syncMeta = {
  startMs: Date.now(),
  merchantsTotal: 0,
  merchantsOk: 0,
  merchantsFail: 0,
};
return [{ json: { sync_started: true } }];

const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.stockRows)) sd.stockRows = [];

const merchantId = $('Loop Merchants').item.json.merchant_id;
const payload = $input.first().json;
const items = Array.isArray(payload.items) ? payload.items : [];

function toSku(raw) {
  const digits = String(raw || '').match(/(\d+)/);
  if (!digits) return String(raw || '').toUpperCase();
  return `SKU-${digits[1].padStart(3, '0')}`;
}

for (const it of items) {
  sd.stockRows.push({
    merchant_id: merchantId,
    sku: toSku(it.sku),
    qty: Number(it.qty),
    synced_at: payload.as_of || new Date().toISOString(),
  });
}
sd.syncMeta.merchantsOk += 1;
return [{ json: { merchant_id: merchantId, ok: true } }];

const sd = $getWorkflowStaticData('global');
sd.syncMeta.merchantsFail += 1;
return [{ json: { merchant_id: $('Loop Merchants').item.json.merchant_id, failed: true } }];

const sd = $getWorkflowStaticData('global');
const rows = Array.isArray(sd.stockRows) ? sd.stockRows : [];
if (!rows.length) {
  return [{ json: { empty: true } }];
}
return rows.map((r) => ({ json: { ...r, empty: false } }));

const sd = $getWorkflowStaticData('global');
const meta = sd.syncMeta || { startMs: Date.now(), merchantsTotal: 0, merchantsOk: 0, merchantsFail: 0 };
const rows = Array.isArray(sd.stockRows) ? sd.stockRows : [];
const prev = Array.isArray(sd.prevPositive) ? sd.prevPositive : [];
const prevSet = new Set(prev.map((p) => `${p.merchant_id}|${p.sku}`));
const newStockouts = [];
for (const r of rows) {
  const key = `${r.merchant_id}|${String(r.sku).toUpperCase()}`;
  if (Number(r.qty) === 0 && prevSet.has(key)) {
    newStockouts.push({ merchant_id: r.merchant_id, sku: r.sku, qty: 0 });
  }
}
sd.newStockouts = newStockouts;
const duration_ms = Date.now() - (meta.startMs || Date.now());
return [{
  json: {
    merchants_total: meta.merchantsTotal || 0,
    merchants_ok: meta.merchantsOk || 0,
    merchants_fail: meta.merchantsFail || 0,
    rows_synced: rows.length,
    new_stockouts: newStockouts.length,
    new_stockout_list: newStockouts.slice(0, 20),
    duration_ms,
  },
}];

