const body = $input.first().json;
const items = Array.isArray(body.items) ? body.items : [];
const itemsNormalized = items.map((i) => ({
  sku: String(i.sku).toUpperCase(),
  qty: Number(i.qty),
}));
return [{ json: { ...body, items_normalized: itemsNormalized } }];

const order = $('Prepare Stock Check').first().json;
const rows = $input.all().map((i) => i.json);
const bySku = {};
for (const r of rows) bySku[String(r.sku).toUpperCase()] = Number(r.qty_available);

// Ambang stok tipis: stok tersedia cukup untuk order, tetapi sisa/stok saat ini <= 10
const TIPIS_MAX = 10;
let route = 'cukup';
for (const item of order.items_normalized) {
  const avail = bySku[item.sku] ?? 0;
  if (avail < item.qty) { route = 'habis'; break; }
}
if (route !== 'habis') {
  for (const item of order.items_normalized) {
    const avail = bySku[item.sku] ?? 0;
    if (avail <= TIPIS_MAX) { route = 'tipis'; break; }
  }
}
return [{ json: { ...order, stock_route: route, stock_tipis_threshold: TIPIS_MAX } }];

const sd = $getWorkflowStaticData('global');
sd.prevPositive = $input.all().map((i) => ({
  merchant_id: i.json.merchant_id,
  sku: String(i.json.sku).toUpperCase(),
  qty: Number(i.json.qty),
}));
return [{ json: { prev_positive: sd.prevPositive.length } }];

const kpi = $('Compute Daily KPI').first().json;
const spot = $('Prepare MCP Cancel Args').first().json;
const reasons = $input.all().map((i) => i.json);
const NL = String.fromCharCode(10);

function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function code(s) {
  return '<code>' + esc(s) + '</code>';
}

function labelReason(codeText) {
  return String(codeText || '').replace(/_/g, ' ');
}

function pct(n) {
  const x = Number(n);
  if (!Number.isFinite(x)) return String(n ?? '-');
  return (x <= 1 ? x * 100 : x).toFixed(1) + '%';
}

function reasonRowsFromMcp(value, out) {
  if (value == null) return;
  if (typeof value === 'string') {
    try { reasonRowsFromMcp(JSON.parse(value), out); } catch (e) {}
    return;
  }
  if (Array.isArray(value)) {
    for (const x of value) reasonRowsFromMcp(x, out);
    return;
  }
  if (typeof value === 'object') {
    if (value.cancel_reason != null) {
      out.push({ cancel_reason: value.cancel_reason, jumlah: value.jumlah ?? '?' });
      return;
    }
    if (value.content != null) reasonRowsFromMcp(value.content, out);
    if (value.text != null) reasonRowsFromMcp(value.text, out);
    if (value.json != null) reasonRowsFromMcp(value.json, out);
    if (value.data != null) reasonRowsFromMcp(value.data, out);
  }
}

const allRows = reasons.filter((r) => r.cancel_reason != null).slice(0, 3);

let mcpRows = [];
try {
  for (const item of $('MCP Client Cancel Reasons').all()) {
    reasonRowsFromMcp(item.json, mcpRows);
  }
  mcpRows = mcpRows.slice(0, 3);
} catch (e) {}

const reportDate = String(kpi.report_date || spot.order_date || '').slice(0, 10);

const digest_text = [
  '<b>H8Mart Ops · Daily Digest</b>',
  '',
  'Date: ' + code(reportDate),
  'Orders: ' + code(kpi.orders_total),
  'Cancel rate: ' + code(pct(kpi.cancel_rate)),
  'On-time delivery: ' + code(pct(kpi.sla_on_time_rate)) + ' (' + code(kpi.delivered_on_time) + ' of ' + code(kpi.delivered_total) + ')',
  '',
  '<b>Top cancel reasons (all merchants)</b>',
  allRows.length
    ? allRows.map((r) => '• ' + esc(labelReason(r.cancel_reason)) + ' — ' + code(r.jumlah)).join(NL)
    : '• none',
  '',
  '<b>Highest cancel volume: ' + code(spot.merchant_id) + '</b>',
  mcpRows.length
    ? mcpRows.map((r) => '• ' + esc(labelReason(r.cancel_reason)) + ' — ' + code(r.jumlah)).join(NL)
    : '• none',
].join(NL);

return [{
  json: {
    ...kpi,
    report_date: reportDate,
    top_cancel_reasons: allRows.map((r) => r.cancel_reason + ': ' + r.jumlah).join(' | ') || 'n/a',
    digest_text,
  },
}];

const kpi = $('Compute Daily KPI').first().json;
const row = $input.first().json || {};
const rawDate = String(row.order_date || kpi.report_date || '');
const order_date = (rawDate.match(/^\d{4}-\d{2}-\d{2}/) || [rawDate.slice(0, 10)])[0];
return [{
  json: {
    merchant_id: String(row.merchant_id || 'M001'),
    order_date,
    merchant_name: row.merchant_name || row.merchant_id || 'M001',
    cancel_fail_count: Number(row.cancel_fail_count || 0),
  },
}];
